"use client"

// AsciiArt — "HANZO Network LED Dots", made with the 21st ASCII editor and baked
// to its exact rendered output (looping video + poster). Zero dependencies:
// one <video> that fills its parent. Drop it behind or inside your content:
// <div className="relative h-96"><AsciiArt className="absolute inset-0" /></div>
// Remix the source recipe (styles, animation, palette) in the editor:
// https://21st.dev/community/ascii/editor?from=44b695f5-8859-4398-9f6f-da182c28a895
export function AsciiArt({ className }: { className?: string }) {
  return (
    <video
      className={className}
      src={"https://assets.21st.dev/ascii-recipes/videos/user_3GPGUGW0kezwI1M261bFhugwynL/d68c94ed-93ee-4a94-a29a-a57fba820147.mp4"}
      poster={"https://assets.21st.dev/ascii-recipes/thumbnails/user_3GPGUGW0kezwI1M261bFhugwynL/d6d84de2-7d85-4f4c-ae7f-86018cd0d8e0.webp"}
      autoPlay
      loop
      muted
      playsInline
      aria-label={"HANZO Network LED Dots — animated ASCII art"}
      style={{
        display: "block",
        width: "100%",
        height: "100%",
        objectFit: "cover",
      }}
    />
  )
}

